1. function helper(n, finalLen) {
2.   if (n == 0) return [''];
3.   if (n == 1) return ['0', '1', '8'];
4.   let prev = helper(n - 2, finalLen);
5.   let res = [];
6.   for (let s of prev) {
7.     if (n != finalLen) res.push('0' + s + '0');
8.     res.push('1' + s + '1', '6' + s + '9', '8' + s + '8', '9' + s + '6');
9.   }
10.  return res;
11. }
